import { useState, useEffect, useId } from 'react'
import type { FormEvent } from 'react'
import { useNavigate, useLocation, Navigate, Link } from 'react-router-dom'
import { z } from 'zod'

import { useAppDispatch, useAppSelector } from '../../store/hooks'
import { signIn, registerFamilyUser } from '../../store/slices/authSlice'
import { AuthHero } from '../../components/auth/AuthHero'
import { AuthRoleSelector } from '../../components/auth/AuthRoleSelector'
import { PasswordField } from '../../components/auth/PasswordField'
import logoUrl from '../../assets/logo.png'
import loginBg from '../../assets/Loging.webp'
import registerBg from '../../assets/Register.webp'

import '../../styles/auth-shell.css'

// ── Validation schemas ────────────────────────────────────────────────────────

const signInSchema = z.object({
  email:    z.string().email('Enter a valid email address.'),
  password: z.string().min(1, 'Enter your password.'),
})

const registrationSchema = z.object({
  displayName: z.string().trim().min(1, 'Enter your full name.').max(120),
  email:       z.string().email('Enter a valid email address.'),
  password:    z.string().min(12, 'Use at least 12 characters.').max(128),
  role:        z.enum(['FAMILY', 'MEMBER', 'DOCTOR']),
})

// ── Component ─────────────────────────────────────────────────────────────────

export function AuthPage() {
  const dispatch  = useAppDispatch()
  const navigate  = useNavigate()
  const location  = useLocation()
  const uid       = useId()

  const { isAuthenticated, user, status: authStatus, error: authError } = useAppSelector((s) => s.auth)

  // Mode — driven by URL
  const isRegisterRoute = location.pathname.includes('/register')
  const [isSignUpMode, setIsSignUpMode] = useState(isRegisterRoute)

  // Login state
  const [loginEmail,    setLoginEmail]    = useState('')
  const [loginPassword, setLoginPassword] = useState('')
  const [rememberMe,    setRememberMe]    = useState(false)
  const [loginError,    setLoginError]    = useState('')

  // Register state
  const [role,        setRole]        = useState<'FAMILY' | 'MEMBER' | 'DOCTOR'>('FAMILY')
  const [regName,     setRegName]     = useState('')
  const [regEmail,    setRegEmail]    = useState('')
  const [regPassword, setRegPassword] = useState('')
  const [regError,    setRegError]    = useState('')

  // Sync mode with route
  useEffect(() => {
    setIsSignUpMode(location.pathname.includes('/register'))
    const params = new URLSearchParams(location.search)
    if (params.get('role') === 'DOCTOR') setRole('DOCTOR')
  }, [location])

  // Redirect authenticated users
  if (isAuthenticated) {
    if (user?.role === 'DOCTOR' && user?.verificationStatus !== 'VERIFIED')
      return <Navigate to="/doctor-status" replace />
    return <Navigate to={user?.role === 'ONBOARDING' ? '/onboarding' : '/dashboard'} replace />
  }

  // Toggle login ↔ register (updates URL)
  function toggleMode() {
    navigate(isSignUpMode ? '/login' : '/register', { replace: true })
  }

  // ── Login ─────────────────────────────────────────────────────────────────

  async function handleLogin(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setLoginError('')
    const parsed = signInSchema.safeParse({ email: loginEmail, password: loginPassword })
    if (!parsed.success) {
      setLoginError(parsed.error.issues[0]?.message ?? 'Check the form and try again.')
      return
    }
    const result = await dispatch(signIn(parsed.data))
    if (signIn.rejected.match(result)) return

    const destination =
      result.payload.role === 'ONBOARDING'
        ? '/onboarding'
        : result.payload.role === 'DOCTOR' && result.payload.verificationStatus !== 'VERIFIED'
        ? '/doctor-status'
        : (location.state as { from?: string } | null)?.from ?? '/dashboard'
    navigate(destination, { replace: true })
  }

  // ── Register ──────────────────────────────────────────────────────────────

  async function handleRegister(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setRegError('')

    // Doctor registration → dedicated page with 3-step stepper
    if (role === 'DOCTOR') {
      navigate('/register/doctor', { replace: true })
      return
    }

    const parsed = registrationSchema.safeParse({
      displayName: regName, email: regEmail, password: regPassword, role,
    })
    if (!parsed.success) {
      setRegError(parsed.error.issues[0]?.message ?? 'Check the form.')
      return
    }

    if (role === 'FAMILY') {
      const result = await dispatch(registerFamilyUser({
        displayName: regName, email: regEmail, password: regPassword,
      }))
      if (registerFamilyUser.fulfilled.match(result)) navigate('/onboarding', { replace: true })
    } else {
      // MEMBER — invitation flow
      const result = await dispatch(registerFamilyUser({
        displayName: regName, email: regEmail, password: regPassword,
      }))
      if (registerFamilyUser.fulfilled.match(result)) navigate('/onboarding', { replace: true })
    }
  }

  const isLoading = authStatus === 'loading'
  const mode = isSignUpMode ? 'register' : 'login'

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <main
      className="auth-shell-page"
      aria-label={isSignUpMode ? 'Create account' : 'Sign in'}
    >
      <div className="auth-container" data-mode={mode}>

        {/* ── Hero ── */}
        <AuthHero
          imageSrc={isSignUpMode ? registerBg : loginBg}
          logoSrc={logoUrl}
          headline={
            isSignUpMode
              ? 'Join FamilyVeda today.'
              : 'Care connected around your family.'
          }
          subline={
            isSignUpMode
              ? 'Choose your role and create your account.'
              : 'Secure access to your health, family and clinical care.'
          }
        />

        {/* ── Form panel ── */}
        <div className="auth-form-panel">

          {/* Small logo mark in form */}
          <div className="auth-form-logo-mark">
            <img src={logoUrl} alt="" aria-hidden="true" width={32} height={32} />
            <span className="auth-form-logo-mark-name">FamilyVeda</span>
          </div>

          {/* ── LOGIN FORM ── */}
          {!isSignUpMode && (
            <section aria-labelledby={`${uid}-login-heading`}>
              <h1 id={`${uid}-login-heading`} className="auth-form-title">Welcome back</h1>
              <p className="auth-form-subtitle">Sign in to continue to FamilyVeda.</p>

              {(loginError || authError) && (
                <div className="auth-alert-error" role="alert">
                  <span aria-hidden="true">⚠</span>
                  <span>{loginError || authError}</span>
                </div>
              )}

              <form onSubmit={handleLogin} noValidate>
                {/* Email */}
                <div className="auth-field">
                  <label htmlFor={`${uid}-email`}>Email address</label>
                  <input
                    id={`${uid}-email`}
                    type="email"
                    value={loginEmail}
                    required
                    autoComplete="email"
                    placeholder="you@example.com"
                    aria-invalid={loginError ? 'true' : undefined}
                    onChange={(e) => setLoginEmail(e.target.value)}
                  />
                </div>

                {/* Password */}
                <PasswordField
                  id={`${uid}-pw`}
                  label="Password"
                  value={loginPassword}
                  autoComplete="current-password"
                  placeholder="Enter your password"
                  required
                  onChange={setLoginPassword}
                />

                {/* Remember me + Forgot */}
                <div className="auth-check-row">
                  <label className="auth-check-label">
                    <input
                      type="checkbox"
                      checked={rememberMe}
                      onChange={(e) => setRememberMe(e.target.checked)}
                    />
                    Remember me
                  </label>
                  <Link to="/forgot-password" className="auth-forgot-link">
                    Forgot password?
                  </Link>
                </div>

                <button
                  type="submit"
                  className="auth-btn-primary"
                  disabled={isLoading}
                  aria-busy={isLoading}
                >
                  {isLoading
                    ? <><span className="auth-spinner" aria-hidden="true" /> Signing in…</>
                    : 'Sign In'
                  }
                </button>
              </form>

              <div className="auth-switch-row">
                New to FamilyVeda?{' '}
                <button type="button" onClick={toggleMode}>Create an account</button>
              </div>
            </section>
          )}

          {/* ── REGISTER FORM ── */}
          {isSignUpMode && (
            <section aria-labelledby={`${uid}-reg-heading`}>
              <h1 id={`${uid}-reg-heading`} className="auth-form-title">
                Create your FamilyVeda account
              </h1>
              <p className="auth-form-subtitle">Choose your role and enter your details.</p>

              {/* Role selector cards */}
              <AuthRoleSelector value={role} onChange={setRole} />

              {/* Doctor shortcut */}
              {role === 'DOCTOR' && (
                <div className="auth-alert-info">
                  Doctor registration requires additional professional details.
                  You will be taken to a dedicated registration form.
                </div>
              )}

              {(regError || authError) && (
                <div className="auth-alert-error" role="alert">
                  <span aria-hidden="true">⚠</span>
                  <span>{regError || authError}</span>
                </div>
              )}

              <form onSubmit={handleRegister} noValidate>
                {/* Full name */}
                <div className="auth-field">
                  <label htmlFor={`${uid}-rname`}>
                    Full name <span aria-hidden="true">*</span>
                  </label>
                  <input
                    id={`${uid}-rname`}
                    type="text"
                    value={regName}
                    required={role !== 'DOCTOR'}
                    autoComplete="name"
                    placeholder="Jane Smith"
                    maxLength={120}
                    onChange={(e) => setRegName(e.target.value)}
                  />
                </div>

                {/* Email */}
                <div className="auth-field">
                  <label htmlFor={`${uid}-remail`}>
                    Email address <span aria-hidden="true">*</span>
                  </label>
                  <input
                    id={`${uid}-remail`}
                    type="email"
                    value={regEmail}
                    required={role !== 'DOCTOR'}
                    autoComplete="email"
                    placeholder="you@example.com"
                    onChange={(e) => setRegEmail(e.target.value)}
                  />
                </div>

                {/* Password — not shown when redirecting doctor to separate page */}
                {role !== 'DOCTOR' && (
                  <PasswordField
                    id={`${uid}-rpw`}
                    label="Password"
                    value={regPassword}
                    autoComplete="new-password"
                    placeholder="Min 12 characters"
                    required
                    showStrength
                    onChange={setRegPassword}
                  />
                )}

                <button
                  type="submit"
                  className="auth-btn-primary"
                  disabled={isLoading}
                  aria-busy={isLoading}
                  style={{ marginTop: '8px' }}
                >
                  {isLoading
                    ? <><span className="auth-spinner" aria-hidden="true" /> Creating account…</>
                    : role === 'DOCTOR' ? 'Continue to Doctor Registration' : 'Create Account'
                  }
                </button>
              </form>

              <div className="auth-switch-row">
                Already have an account?{' '}
                <button type="button" onClick={toggleMode}>Sign in</button>
              </div>
            </section>
          )}
        </div>
      </div>
    </main>
  )
}
